// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Query constants are resolved to dictionary IDs once per dictionary revision and remembered across queries. These
 * tests pin what that memo must never do: answer for a value the dictionary no longer holds under that ID, or hide a
 * value that was added after an earlier query missed it.
 */
class LmdbStatementIdMemoTest {

	private static final ValueFactory VALUES = SimpleValueFactory.getInstance();
	private static final IRI SUBJECT = VALUES.createIRI("urn:memo:subject");
	private static final IRI PREDICATE = VALUES.createIRI("urn:memo:predicate");
	private static final IRI OTHER_PREDICATE = VALUES.createIRI("urn:memo:other-predicate");
	private static final IRI OBJECT = VALUES.createIRI("urn:memo:object");
	private static final Literal PLAIN = VALUES.createLiteral("a label that is too long to be stored inline");
	private static final Literal TAGGED = VALUES.createLiteral("a label that is too long to be stored inline", "en");

	@Test
	void repeatedConstantsKeepAnsweringFromTheCurrentDictionary(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(SUBJECT, PREDICATE, OBJECT);
			connection.add(SUBJECT, OTHER_PREDICATE, PLAIN);
			connection.add(OBJECT, OTHER_PREDICATE, TAGGED);

			for (int repeat = 0; repeat < 3; repeat++) {
				assertEquals(List.of(OBJECT),
						select(connection, "SELECT ?v WHERE { <urn:memo:subject> <urn:memo:predicate> ?v }"));
				assertEquals(List.of(SUBJECT), select(connection, "SELECT ?v WHERE { ?v <urn:memo:other-predicate> "
						+ "\"a label that is too long to be stored inline\" }"));
				assertEquals(List.of(OBJECT), select(connection, "SELECT ?v WHERE { ?v <urn:memo:other-predicate> "
						+ "\"a label that is too long to be stored inline\"@en }"));
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void constantsResolvedBeforeAClearAreLookedUpAgain(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(SUBJECT, PREDICATE, OBJECT);
			String byPredicate = "SELECT ?v WHERE { <urn:memo:subject> <urn:memo:predicate> ?v }";
			String byOtherPredicate = "SELECT ?v WHERE { ?s <urn:memo:other-predicate> ?v }";
			assertEquals(List.of(OBJECT), select(connection, byPredicate));
			assertEquals(List.of(OBJECT), select(connection, byPredicate));

			connection.clear();
			assertEquals(List.of(), select(connection, byPredicate));

			// Refilled in another order: an ID remembered from before the clear would now name another value.
			connection.add(OBJECT, OTHER_PREDICATE, PLAIN);
			connection.add(PREDICATE, OTHER_PREDICATE, SUBJECT);
			connection.add(SUBJECT, PREDICATE, TAGGED);

			assertEquals(List.of(TAGGED), select(connection, byPredicate));
			assertEquals(List.of(TAGGED), select(connection, byPredicate));
			List<Value> others = select(connection, byOtherPredicate);
			assertEquals(2, others.size());
			assertEquals(true, others.contains(PLAIN) && others.contains(SUBJECT));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void aConstantMissedOnceIsFoundAfterItIsAdded(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(SUBJECT, PREDICATE, OBJECT);
			String query = "SELECT ?v WHERE { <urn:memo:object> <urn:memo:other-predicate> ?v }";
			assertEquals(List.of(), select(connection, query));
			assertEquals(List.of(), select(connection, query));

			connection.add(OBJECT, OTHER_PREDICATE, PLAIN);
			assertEquals(List.of(PLAIN), select(connection, query));

			connection.remove(OBJECT, OTHER_PREDICATE, PLAIN);
			assertEquals(List.of(), select(connection, query));
			assertEquals(List.of(OBJECT),
					select(connection, "SELECT ?v WHERE { <urn:memo:subject> <urn:memo:predicate> ?v }"));
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void aShortLabelDoesNotAdmitAnOversizedDatatype(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		try (SailRepositoryConnection connection = repository.getConnection()) {
			IRI datatype = VALUES.createIRI("urn:memo:datatype:" + "d".repeat(8 * 1024));
			Literal typed = VALUES.createLiteral("a short label with a very long datatype", datatype);
			connection.add(SUBJECT, OTHER_PREDICATE, typed);
			connection.add(SUBJECT, PREDICATE, OBJECT);

			String query = "SELECT ?v WHERE { ?v <urn:memo:other-predicate> \"" + typed.getLabel() + "\"^^<"
					+ datatype.stringValue() + "> }";
			for (int repeat = 0; repeat < 3; repeat++) {
				assertEquals(List.of(SUBJECT), select(connection, query));
			}
			// An ordinary constant, so the memo is known to be in use for this store.
			assertEquals(List.of(OBJECT),
					select(connection, "SELECT ?v WHERE { <urn:memo:subject> <urn:memo:predicate> ?v }"));

			ValueStore valueStore = valueStore(connection);
			assertTrue(valueStore.statementIdMemoLongestKey() > 0, "the memo must hold the ordinary constants");
			assertTrue(valueStore.statementIdMemoLongestKey() < datatype.stringValue().length(),
					"the memo outlives the snapshot and must not retain the oversized datatype");
		} finally {
			repository.shutDown();
		}
	}

	private static ValueStore valueStore(SailRepositoryConnection connection) {
		try (var statements = connection.getStatements(SUBJECT, PREDICATE, null)) {
			return ((LmdbValue) statements.next().getSubject()).getValueStoreRevision().getValueStore();
		}
	}

	private static List<Value> select(SailRepositoryConnection connection, String query) {
		List<Value> values = new ArrayList<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				values.add(result.next().getValue("v"));
			}
		}
		return values;
	}
}
